 function lock(c,target){if(c.testOnly)return null;const ls=settings(c.year).locks.filter(l=>l.target===target&&(l.scope==='year'||l.scope==='student'&&l.studentId===c.user.id||l.scope==='class'&&l.grade===c.user.grade&&l.classNo===c.user.classNo));ls.sort((a,b)=>({year:0,class:1,student:2}[a.scope])-({year:0,class:1,student:2}[b.scope]));const l=ls.at(-1);return l?.locked?l:null}
