 function pick(c,mode){const history=knowledge(c),day=calendar(now()).day;return sample(quizEvents.map(e=>{const qs=e.questions.filter(q=>q.mode===mode&&!lock(c,q.id));must(qs.length,'CONTENT_INCOMPLETE',e.title+'의 사용 가능한 문항이 없습니다. 교사에게 문의하세요.');const grade=q=>{const r=history.find(x=>x.questionId===q.id);return !r?.successAt?0:!r.days?.[day]?1:r.lastWrongAt&&r.lastWrongAt>r.lastSuccessAt?2:3};return sample(qs).sort((a,b)=>grade(a)-grade(b)||String(history.find(x=>x.questionId===a.id)?.lastSuccessAt||'').localeCompare(String(history.find(x=>x.questionId===b.id)?.lastSuccessAt||'')))[0].id}))}
