 function daily(c){allow(c,'game');must(!c.testOnly,'TEST_ONLY','교사 연습모드에는 출석 보상을 지급하지 않습니다.');const cal=calendar(now()),rw=rewards(c.year),key=c.user.id+':'+uid+':'+cal.day;if(get('attendance',key))return{claimed:false,student:state(c)};if(!rw.weekdays.includes(cal.dow)||rw.excludedDates.includes(cal.day))return{claimed:false,student:state(c)};const past=all('attendance').filter(x=>x.studentId===c.user.id&&x.unitId===uid).sort((a,b)=>b.date.localeCompare(a.date))[0];let prev=new Date(cal.day+'T00:00:00+09:00').getTime()-86400000;for(let i=0;i<370;i++,prev-=86400000){const k=calendar(prev);if(rw.weekdays.includes(k.dow)&&!rw.excludedDates.includes(k.day))break}const continued=past?.date===calendar(prev).day,day=continued?(past.cycleDay%rw.attendance.cycleDays)+1:1,total=continued?past.totalDays+1:1;put('attendance',{id:key,schoolYear:c.year,studentId:c.user.id,unitId:uid,date:cal.day,cycleDay:day,totalDays:total,createdAt:iso(now())});const ar=rw.attendance,min=day===ar.mythDay&&ar.mythDay>0?4:day===ar.legendDay?3:day===ar.uniqueDay?2:day===ar.rareDay?1:0;addPacks(c,c.user,uid,'basic',rw.dailyCards,min);return{claimed:true,student:state(c)}}
