 function targetStudents(c,p){const year=number(p.schoolYear||c.year,2020,2200);const scope=p.scope||'student';must(['student','class','grade','year','all'].includes(scope),'INVALID_SCOPE','대상 범위를 확인하세요.');if(scope==='student')must(typeof p.studentId==='string','INVALID_SCOPE','학생을 선택하세요.');if(['class','grade'].includes(scope))number(p.grade,1,6);if(scope==='class')number(p.classNo,1,99);return all('students').filter(u=>(scope==='all'||u.schoolYear===year)&&(scope!=='student'||u.id===p.studentId)&&(!['class','grade'].includes(scope)||u.grade===p.grade)&&(scope!=='class'||u.classNo===p.classNo))}
