 function validateRewards(v){for(const p of rules.packs){const o=v.packs[p.id];must(o&&R.every(r=>Number.isFinite(o[r])&&o[r]>=0&&o[r]<=100)&&Math.abs(R.reduce((s,r)=>s+o[r],0)-100)<.001,'INVALID_ODDS','확률 합계는 100%여야 합니다.');if(p.fixed)must(equal(o,p.odds),'FIXED_PACK','확정팩 확률은 변경할 수 없습니다.')}for(const k of ['basicAfter','premiumAfter','eliteAfter','mythAfter'])number(v.pity[k],0,10000);number(v.dailyCards,0,20);number(v.eventMultiplier,1,10);must(rules.packs.some(p=>p.id===v.eventPack),'INVALID_PACK','보상 팩을 확인하세요.');must((!v.eventFrom&&!v.eventUntil)||(Date.parse(v.eventUntil)>Date.parse(v.eventFrom)),'INVALID_TIME','이벤트 시작·종료 시각을 확인하세요.');must(Array.isArray(v.weekdays)&&v.weekdays.length>0&&v.weekdays.every(x=>Number.isInteger(x)&&x>=0&&x<=6),'INVALID_SETTING','출석 요일을 확인하세요.');must(Array.isArray(v.excludedDates)&&v.excludedDates.every(x=>/^\d{4}-\d\d-\d\d$/.test(x)),'INVALID_SETTING','제외 날짜 형식을 확인하세요.');number(v.attendance.cycleDays,1,365);for(const k of ['rareDay','uniqueDay','legendDay','mythDay'])number(v.attendance[k],0,v.attendance.cycleDays);must(Array.isArray(v.missions)&&v.missions.length<=30&&new Set(v.missions.map(x=>x.id)).size===v.missions.length,'INVALID_MISSION','미션은 중복 없이 30개 이하입니다.');for(const m of v.missions){text(m.id,80);text(m.title,100);number(m.target,1,1000);number(m.rewardCount,1,20);number(m.conditionValue,0,3600);must(typeof m.active==='boolean'&&['daily','weekly','monthly'].includes(m.period)&&['any',...MODES].includes(m.game)&&['complete','sets','time'].includes(m.metric)&&rules.packs.some(p=>p.id===m.reward),'INVALID_MISSION','미션 설정을 확인하세요.')}}
 function gift(c,p,req){teacher(c);must((p.unitId||uid)===uid,'NOT_READY','현재 연결된 프랑스혁명 카드만 지급할 수 있습니다.');const users=targetStudents(c,p);must(users.length>0&&users.length<=100,'BATCH_LIMIT','한 번에 1~100명을 지정하세요.');const count=number(p.count,1,50),results=[];must(['pack','card'].includes(p.kind),'INVALID_GIFT','지급 종류를 확인하세요.');for(const u of users){let given=0;if(p.kind==='pack'){must(p.unowned!==true,'INVALID_GIFT','미보유 지급은 카드 직접 지급에서 선택하세요.');addPacks(c,u,uid,p.packId,count);given=count}else{must(p.rarity==='random'||R.includes(p.rarity),'INVALID_RARITY','등급을 확인하세요.');must(p.eventId==='random'||Number.isInteger(p.eventId)&&p.eventId>=1&&p.eventId<=14,'INVALID_EVENT','사건을 확인하세요.');for(let i=0;i<count;i++){let pool=rules.collections.filter(e=>p.eventId==='random'||e.id===p.eventId).flatMap(e=>(p.rarity==='random'?R:[p.rarity]).map(r=>({e,r})));if(p.unowned)pool=pool.filter(x=>!(get('cards',u.id+':'+uid+':'+x.e.id+':'+x.r)?.count>0));if(!pool.length)break;const x=sample(pool,1)[0];addCard(c,u,x.e,x.r);given++}}results.push({studentId:u.id,given})}audit(c,'gift',{criteria:p},null,results,req);return{results}}
 function review(c,p,req){teacher(c);const r=get('records',text(p.recordId));must(r,'NOT_FOUND','기록이 없습니다.');must(['normal','excluded'].includes(p.status),'INVALID_STATUS','처리 상태를 확인하세요.');const reason=text(p.reason,300);must(reason.length>=2,'REASON_REQUIRED','처리 사유를 입력하세요.');const before=clone(r);r.status=p.status;r.reason=reason;put('records',r);const sr=get('speed',r.id);if(sr){sr.status=r.status;put('speed',sr)}audit(c,'record.review',{recordId:r.id},before,r,req);return{record:r}}
